namespace ghidra.app.plugin.debug;



using db;
using docking;
using generic.theme;
using ghidra.framework.plugintool;
using ghidra.framework.plugintool;
using ghidra.util;

public class DbViewerProvider : ComponentProviderAdapter {

	private DBHandle dbh;
	private string dbName;
	private DbViewerComponent comp;

	public DbViewerProvider(Plugin plugin) : base(plugin.getTool(), "Database Viewer", plugin.getName())
    {

		setIcon(new GIcon("icon.plugin.debug.dbviewer.provider"));
		setDefaultWindowPosition(WindowPosition.BOTTOM);

		setHelpLocation(new HelpLocation(plugin.getName(), "DbViewer"));
	}

	protected void closeDatabase() {
		if (comp != null) {
			comp.closeDatabase();
		}
		dbh = null;
	}

	/**
	 * Opens the database for viewing its table data.
	 * @param databaseName the name of the database.
	 * @param handle the DBHandle for the open database
	 */
	protected void openDatabase(string databaseName, DBHandle handle) {
		if (comp != null) {
			comp.openDatabase(databaseName, handle);
		}
		this.dbh = handle;
		this.dbName = databaseName;
	}

	void refresh() {
		if (comp != null) {
			comp.refresh();
		}
	}

	void dispose() {
		if (comp != null) {
			comp.dispose();
			comp = null;
		}
	}

	/* @Override */
	public JComponent getComponent() {
		if (comp == null) {
			comp = new DbViewerComponent(tool);
			if (dbh != null) {
				comp.openDatabase(dbName, dbh);
			}
		}
		return comp;
	}
}
